const ids = [
  'question-enonce',
  'sticky-parent-enonce',
  'choice-A',
  'choice-B',
  'choice-C',
  'choice-D',
  'choice-E'
];

const elements = ids
  .map(id => document.getElementById(id))
  .filter(Boolean);

// Petite attente pour laisser WeWeb injecter le DOM
await new Promise(resolve => setTimeout(resolve, 100));

// Attendre MathJax si disponible
if (window.MathJax?.typesetPromise && elements.length > 0) {
  try {
    await window.MathJax.typesetPromise(elements);
  } catch (e) {
    console.warn('MathJax wait error:', e);
  }
}

// Attendre 2 frames navigateur pour être sûr que le rendu est peint à l’écran
await new Promise(resolve => requestAnimationFrame(() => {
  requestAnimationFrame(resolve);
}));

// Petit buffer final anti-flash
await new Promise(resolve => setTimeout(resolve, 100));

